        public static Npc_FieldIndex ConvertFieldIndex(FalloutNVMajorRecord_FieldIndex index)
        {
            switch (index)
            {
                case FalloutNVMajorRecord_FieldIndex.MajorRecordFlagsRaw:
                    return (Npc_FieldIndex)((int)index);
                case FalloutNVMajorRecord_FieldIndex.FormKey:
                    return (Npc_FieldIndex)((int)index);
                case FalloutNVMajorRecord_FieldIndex.VersionControl:
                    return (Npc_FieldIndex)((int)index);
                case FalloutNVMajorRecord_FieldIndex.EditorID:
                    return (Npc_FieldIndex)((int)index);
                case FalloutNVMajorRecord_FieldIndex.FormVersion:
                    return (Npc_FieldIndex)((int)index);
                case FalloutNVMajorRecord_FieldIndex.Version2:
                    return (Npc_FieldIndex)((int)index);
