        public Npc Duplicate(
            INpcGetter item,
            FormKey formKey,
            TranslationCrystal? copyMask)
        {
            var newRec = new Npc(formKey, default(FalloutNVRelease));
            newRec.DeepCopyIn(item, default(ErrorMaskBuilder?), copyMask);
            return newRec;
        }
        
